import { Text } from "@/shared/ui/typography/Text";
import { SessionDock } from "@/shared/ui/layouts/SessionDock";

// The real ArchitectTerminal drops a <TerminalSlot> into SessionDock's body — the app-level
// TerminalHost re-parents the ONE live PTY terminal into it (same non-presentational mount as
// TerminalView's real internals, no design-time appearance of its own). This preview vendors the
// genuinely visual part — the SessionDock shell — with a themed placeholder standing in for the
// live terminal body.
const TERM_BG = "#181a1f";
const TERM_FG = "#eeeae4";
const TERM_DIM = "#44474f";

export function ArchitectTerminal({ height = 220 }) {
  return (
    <SessionDock
      testid="architect-terminal"
      height={height}
      title="◆ Team architect · teams & personas via bsc"
      subtitle="teams-studio · restricted"
    >
      <div style={{ height: "100%", background: TERM_BG, padding: "6px 10px", fontFamily: '"JetBrains Mono", monospace', fontSize: 12.5, lineHeight: 1.5 }}>
        <Text as="div" style={{ color: TERM_FG }}>$ bsc-agent architect</Text>
        <Text as="div" style={{ color: TERM_DIM }}>Standing by for team &amp; persona changes...</Text>
      </div>
    </SessionDock>
  );
}
